using BARANG.Core.Application.Abstractions.Actors;
using BARANG.Core.Application.Abstractions.Companies;
using BARANG.Core.Application.Abstractions.Transactions;
using BARANG.Core.Application.Auditing;
using BARANG.Core.Application.Finance;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Customers;
using BARANG.Core.Domain.Finance;
using BARANG.Core.Domain.Orders;
using BARANG.Core.Domain.Pricing;
using BARANG.Core.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Storage;

namespace BARANG.Core.Infrastructure.Finance;
#pragma warning disable CA1725,CA1862
public sealed class FinanceAdministration(CoreDbContext db,ITransactionExecutor tx,ICompanyContext company,ICurrentActor actor,IAuditWriter audit,TimeProvider time):IFinanceAdministration
{
    private Guid Company=>company.RequireCompanyId();private Guid Actor=>Guid.TryParse(actor.Actor.UserId,out Guid id)?id:throw new InvalidOperationException("Authenticated user required.");private DateTimeOffset Now=>time.GetUtcNow();
    public Task<Result<IReadOnlyList<PaymentView>>> ListPaymentsAsync(Guid orderId,CancellationToken ct)=>tx.ExecuteAsync(async t=>await db.Orders.AnyAsync(x=>x.Id==orderId,t)?Result.Success<IReadOnlyList<PaymentView>>((await db.Payments.AsNoTracking().Where(x=>x.OrderId==orderId).OrderBy(x=>x.CreatedAtUtc).ThenBy(x=>x.Id).ToListAsync(t)).Select(View).ToArray()):Result.Failure<IReadOnlyList<PaymentView>>(FinanceErrors.NotFound),ct);
    public Task<Result<PaymentView>> RegisterPaymentAsync(Guid orderId,RegisterPaymentCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>
    {
        Order? order=await db.Orders.SingleOrDefaultAsync(x=>x.Id==orderId,t);if(order is null)return Result.Failure<PaymentView>(FinanceErrors.NotFound);if(order.Status!=OrderStatus.Submitted)return Result.Failure<PaymentView>(FinanceErrors.OrderNotEligible);OrderPriceSnapshot? price=await Price(orderId,t);if(price is null)return Result.Failure<PaymentView>(FinanceErrors.PricingRequired);if(!string.Equals(price.CurrencyCode,c.CurrencyCode,StringComparison.OrdinalIgnoreCase))return Result.Failure<PaymentView>(FinanceErrors.CurrencyMismatch);
        string method=Payment.Normalize(c.PaymentMethodCode);bool methodActive=await db.LookupValues.AnyAsync(v=>v.Code==method&&v.IsActive&&db.LookupTypes.Any(lt=>lt.Id==v.LookupTypeId&&lt.Code=="payment.method"&&lt.IsActive),t);if(!methodActive)return Result.Failure<PaymentView>(FinanceErrors.PaymentMethodInactive);
        if(!string.IsNullOrWhiteSpace(c.ReferenceNumber)){Payment? duplicate=await db.Payments.SingleOrDefaultAsync(x=>x.ReferenceNumber==c.ReferenceNumber.Trim(),t);if(duplicate is not null)return duplicate.OrderId==orderId&&duplicate.RecordType==PaymentRecordType.Payment&&duplicate.Amount==Money.Round(c.Amount)&&duplicate.CurrencyCode==price.CurrencyCode?Result.Success(View(duplicate)):Result.Failure<PaymentView>(FinanceErrors.DuplicateReference);}
        Result<Payment> made=Payment.Register(Company,orderId,method,c.Amount,price.CurrencyCode,c.ReferenceNumber,c.PaidAtUtc,Actor,Now);if(made.IsFailure)return Result.Failure<PaymentView>(made.Error);db.Add(made.Value);History(orderId,"PaymentRegistered",made.Value.Id,$"{made.Value.Amount} {made.Value.CurrencyCode}");Log("payment.registered",made.Value.Id);return Result.Success(View(made.Value));
    },ct);
    public Task<Result<PaymentView>> ReversePaymentAsync(Guid orderId,Guid paymentId,ReversePaymentCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>
    {
        Payment? original=await db.Payments.SingleOrDefaultAsync(x=>x.Id==paymentId&&x.OrderId==orderId,t);if(original is null)return Result.Failure<PaymentView>(FinanceErrors.NotFound);decimal reversed=await db.Payments.Where(x=>x.OriginalPaymentId==paymentId&&x.RecordType==PaymentRecordType.Reversal).SumAsync(x=>(decimal?)x.Amount,t)??0;if(reversed>=original.Amount)return Result.Failure<PaymentView>(FinanceErrors.AlreadyReversed);if(c.Amount>original.Amount-reversed)return Result.Failure<PaymentView>(FinanceErrors.InvalidData);if(!string.IsNullOrWhiteSpace(c.ReferenceNumber)){Payment? existing=await db.Payments.SingleOrDefaultAsync(x=>x.ReferenceNumber==c.ReferenceNumber.Trim(),t);if(existing is not null)return existing.OriginalPaymentId==paymentId&&existing.Amount==Money.Round(c.Amount)?Result.Success(View(existing)):Result.Failure<PaymentView>(FinanceErrors.DuplicateReference);}
        Result<Payment> made=Payment.Reverse(original,c.Amount,c.Reason,c.ReferenceNumber,Actor,Now);if(made.IsFailure)return Result.Failure<PaymentView>(made.Error);db.Add(made.Value);History(orderId,"PaymentReversed",made.Value.Id,c.Reason);Log("payment.reversed",made.Value.Id);return Result.Success(View(made.Value));
    },ct);
    public Task<Result<FinanceBalanceView>> GetBalanceAsync(Guid orderId,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(!await db.Orders.AnyAsync(x=>x.Id==orderId,t))return Result.Failure<FinanceBalanceView>(FinanceErrors.NotFound);OrderPriceSnapshot? price=await Price(orderId,t);if(price is null)return Result.Failure<FinanceBalanceView>(FinanceErrors.PricingRequired);return Result.Success(await Balance(price,t));},ct);
    public Task<Result<FinancialStateView>> GetFinancialStateAsync(Guid orderId,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(!await db.Orders.AnyAsync(x=>x.Id==orderId,t))return Result.Failure<FinancialStateView>(FinanceErrors.NotFound);OrderFinancialState? state=await db.OrderFinancialStates.AsNoTracking().SingleOrDefaultAsync(x=>x.OrderId==orderId,t);return Result.Success(state is null?new FinancialStateView(Guid.Empty,orderId,FinancialStatus.Pending,null,null,null,0,null):View(state));},ct);
    public Task<Result<FinancialStateView>> DecideAsync(Guid orderId,FinanceDecisionCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>
    {
        Order? order=await db.Orders.SingleOrDefaultAsync(x=>x.Id==orderId,t);if(order is null)return Result.Failure<FinancialStateView>(FinanceErrors.NotFound);if(order.Status!=OrderStatus.Submitted)return Result.Failure<FinancialStateView>(FinanceErrors.OrderNotEligible);OrderPriceSnapshot? price=await Price(orderId,t);if(price is null)return Result.Failure<FinancialStateView>(FinanceErrors.PricingRequired);OrderFinancialState? state=await db.OrderFinancialStates.SingleOrDefaultAsync(x=>x.OrderId==orderId,t);long expected=c.Version;if(state is null){if(c.Version!=0)return Result.Failure<FinancialStateView>(FinanceErrors.Concurrency);state=OrderFinancialState.Create(Company,orderId,Now);db.Add(state);expected=state.Version;}Result r=state.Transition(c.TargetStatus,c.Reason,Actor,expected,Now,c.TargetStatus==FinancialStatus.Approved?price.Id:null);if(r.IsFailure)return Result.Failure<FinancialStateView>(r.Error);string eventType=c.TargetStatus switch{FinancialStatus.Approved=>"FinanceApproved",FinancialStatus.Rejected=>"FinanceRejected",FinancialStatus.Suspended=>"FinanceSuspended",_=>"FinancePending"};History(orderId,eventType,state.Id,c.Reason);Log(c.TargetStatus switch{FinancialStatus.Approved=>"finance.approved",FinancialStatus.Rejected=>"finance.rejected",FinancialStatus.Suspended=>"finance.suspended",_=>"finance.pending"},state.Id);return Result.Success(View(state));
    },ct);
    public Task<Result<InvoiceView>> GenerateInvoiceAsync(Guid orderId,InvoiceType type,CancellationToken ct)=>tx.ExecuteAsync(async t=>
    {
        if(db.Database.IsNpgsql())await db.Database.ExecuteSqlInterpolatedAsync($"SELECT id FROM barang.orders WHERE company_id={Company} AND id={orderId} FOR UPDATE",t);Invoice? existing=await db.Invoices.AsNoTracking().SingleOrDefaultAsync(x=>x.OrderId==orderId&&x.InvoiceType==type,t);if(existing is not null)return Result.Success(await InvoiceView(existing,t));Order? order=await db.Orders.SingleOrDefaultAsync(x=>x.Id==orderId,t);if(order is null)return Result.Failure<InvoiceView>(FinanceErrors.NotFound);if(order.Status!=OrderStatus.Submitted)return Result.Failure<InvoiceView>(FinanceErrors.OrderNotEligible);OrderPriceSnapshot? price=await Price(orderId,t);if(price is null)return Result.Failure<InvoiceView>(FinanceErrors.PricingRequired);if(type==InvoiceType.Invoice){OrderFinancialState? state=await db.OrderFinancialStates.SingleOrDefaultAsync(x=>x.OrderId==orderId,t);if(state?.Status!=FinancialStatus.Approved)return Result.Failure<InvoiceView>(FinanceErrors.ApprovalRequired);if(state.ApprovedPriceSnapshotId!=price.Id)return Result.Failure<InvoiceView>(FinanceErrors.ApprovalSnapshotMismatch);}Customer customer=await db.Customers.SingleAsync(x=>x.Id==order.CustomerId,t);
        await using System.Data.Common.DbCommand command=db.Database.GetDbConnection().CreateCommand();command.CommandText="SELECT nextval('barang.invoice_number_seq')";command.Transaction=db.Database.CurrentTransaction!.GetDbTransaction();long sequence=Convert.ToInt64(await command.ExecuteScalarAsync(t),System.Globalization.CultureInfo.InvariantCulture);string number=$"{(type==InvoiceType.Proforma?"PRO":"INV")}-{Now.Year}-{sequence:0000000000}";Invoice invoice=Invoice.Create(Company,orderId,price.Id,number,type,Actor,Now);db.Add(invoice);db.Add(InvoiceSnapshot.Create(Company,invoice.Id,order.OrderNumber!,customer.CustomerCode,customer.DisplayName,price));List<OrderItem> orderItems=await db.OrderItems.Where(x=>x.OrderId==orderId&&x.IsActive).OrderBy(x=>x.LineNumber).ToListAsync(t);Dictionary<Guid,OrderItemPriceSnapshot> itemPrices=await db.OrderItemPriceSnapshots.Where(x=>x.OrderPriceSnapshotId==price.Id).ToDictionaryAsync(x=>x.OrderItemId,t);foreach(OrderItem item in orderItems)db.Add(InvoiceItemSnapshot.Create(Company,invoice.Id,item.Id,item.LineNumber,item.SnapshotProductCode!,item.SnapshotProductName!,item.SnapshotVariantSku!,item.Quantity,itemPrices[item.Id]));History(orderId,"InvoiceGenerated",invoice.Id,number);Log("invoice.generated",invoice.Id);return Result.Success(await InvoiceView(invoice,t));
    },ct);
    public Task<Result<IReadOnlyList<InvoiceView>>> ListInvoicesAsync(Guid orderId,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(!await db.Orders.AnyAsync(x=>x.Id==orderId,t))return Result.Failure<IReadOnlyList<InvoiceView>>(FinanceErrors.NotFound);List<InvoiceView> result=[];foreach(Invoice i in await db.Invoices.AsNoTracking().Where(x=>x.OrderId==orderId).OrderBy(x=>x.IssuedAtUtc).ToListAsync(t))result.Add(await InvoiceView(i,t));return Result.Success<IReadOnlyList<InvoiceView>>(result);},ct);
    public Task<Result<IReadOnlyList<FinanceHistoryView>>> HistoryAsync(Guid orderId,CancellationToken ct)=>tx.ExecuteAsync(async t=>await db.Orders.AnyAsync(x=>x.Id==orderId,t)?Result.Success<IReadOnlyList<FinanceHistoryView>>((await db.FinanceHistory.AsNoTracking().Where(x=>x.OrderId==orderId).OrderBy(x=>x.OccurredAtUtc).ThenBy(x=>x.Id).ToListAsync(t)).Select(x=>new FinanceHistoryView(x.Id,x.EventType,x.OccurredAtUtc,x.ActorUserId,x.RelatedEntityId,x.Summary)).ToArray()):Result.Failure<IReadOnlyList<FinanceHistoryView>>(FinanceErrors.NotFound),ct);
    private Task<OrderPriceSnapshot?> Price(Guid order,CancellationToken t)=>db.OrderPriceSnapshots.AsNoTracking().SingleOrDefaultAsync(x=>x.OrderId==order&&x.IsCurrent&&x.IsFinalized,t);
    private async Task<FinanceBalanceView> Balance(OrderPriceSnapshot p,CancellationToken t){decimal paid=await db.Payments.Where(x=>x.OrderId==p.OrderId&&x.RecordType==PaymentRecordType.Payment).SumAsync(x=>(decimal?)x.Amount,t)??0;decimal reversed=await db.Payments.Where(x=>x.OrderId==p.OrderId&&x.RecordType==PaymentRecordType.Reversal).SumAsync(x=>(decimal?)x.Amount,t)??0;decimal net=Money.Round(paid-reversed),remaining=Money.Round(Math.Max(0,p.FinalTotal-net)),over=Money.Round(Math.Max(0,net-p.FinalTotal));return new(p.OrderId,p.FinalTotal,paid,reversed,net,remaining,over,p.CurrencyCode);}
    private async Task<InvoiceView> InvoiceView(Invoice i,CancellationToken t){InvoiceSnapshot? s=await db.InvoiceSnapshots.AsNoTracking().SingleOrDefaultAsync(x=>x.InvoiceId==i.Id,t)??db.InvoiceSnapshots.Local.Single(x=>x.InvoiceId==i.Id);List<InvoiceItemSnapshot> items=await db.InvoiceItemSnapshots.AsNoTracking().Where(x=>x.InvoiceId==i.Id).OrderBy(x=>x.LineNumber).ToListAsync(t);items.AddRange(db.InvoiceItemSnapshots.Local.Where(x=>x.InvoiceId==i.Id&&!items.Any(y=>y.Id==x.Id)).OrderBy(x=>x.LineNumber));return new(i.Id,i.OrderId,i.InvoiceNumber,i.InvoiceType,i.Status,i.IssuedAtUtc,s.OrderNumber,s.CustomerCode,s.CustomerName,s.CurrencyCode,s.Subtotal,s.DiscountTotal,s.TaxTotal,s.FinalTotal,items.Select(x=>new InvoiceItemView(x.LineNumber,x.ProductCode,x.ProductName,x.VariantSku,x.Quantity,x.Subtotal,x.Discount,x.Tax,x.FinalTotal)).ToArray());}
    private void History(Guid order,string type,Guid related,string? summary)=>db.FinanceHistory.Add(FinanceHistory.Create(Company,order,type,Actor,Now,related,summary));private void Log(string action,Guid id)=>audit.Write(new(action,"finance",id.ToString(),ChangeKind:AuditChangeKind.Modified));private static PaymentView View(Payment x)=>new(x.Id,x.OrderId,x.RecordType,x.PaymentMethodCode,x.Amount,x.CurrencyCode,x.ReferenceNumber,x.PaidAtUtc,x.OriginalPaymentId,x.ReversalReason,x.Version);private static FinancialStateView View(OrderFinancialState x)=>new(x.Id,x.OrderId,x.Status,x.Reason,x.DecidedByUserId,x.DecidedAtUtc,x.Version,x.ApprovedPriceSnapshotId);
}
#pragma warning restore CA1725,CA1862
